//! Stage four: a state tree becomes its final files.

use std::collections::BTreeMap;

use meridian_sdk::Value;
use meridian_yaml::Yaml;

use crate::{Reference, Sls, State};

/// The directory of the artifact that is a Salt file root.
pub const STATES_DIR: &str = "states";
/// The top file, which assigns the state file to its minion.
pub const TOP_PATH: &str = "states/top.sls";

/// Where the state file of a document is in the artifact.
pub fn sls_path(name: &str) -> String {
    format!("{STATES_DIR}/{name}.sls")
}

const BANNER: &str =
    "# Generated by Meridian. Do not edit; this file is compiled from a Meridian document.\n";

/// The Jinja variable that stands for an opening brace, see [`Text::escape`].
const BRACE: &str = "meridian_brace";

/// How a state's own arguments are indented, which the condition lines
/// written beside them have to match.
const ARGUMENT_INDENT: &str = "    ";

/// Renders a state file and its top file. This stage performs no mapping and
/// no ordering: everything it writes was decided by transform and sort, so
/// the same tree always renders to the same bytes.
pub(crate) fn serialise(sls: &Sls) -> BTreeMap<String, String> {
    BTreeMap::from([
        (sls_path(&sls.name), state_file(sls)),
        (TOP_PATH.to_owned(), top_file(sls)),
    ])
}

/// The state file.
///
/// Salt renders a state file through Jinja and then YAML unless its first
/// line says otherwise. A file with no runtime condition says otherwise: it
/// is plain YAML, so no text an author wrote can be taken for a template. A
/// file that does carry one needs Jinja, and there every string is written
/// so that Jinja hands it on unchanged.
fn state_file(sls: &Sls) -> String {
    // A secret is read from the pillar through Jinja, so a file that holds
    // one is rendered through Jinja too.
    let text = Text {
        jinja: sls.all().any(|s| {
            !s.when.is_empty()
                || s.args
                    .iter()
                    .any(|(_, v)| crate::transform::holds_secret(v))
        }),
        secrets: &sls.secrets,
    };
    let mut out = String::new();
    if text.jinja {
        out.push_str("#!jinja|yaml\n");
        out.push_str(BANNER);
        out.push_str(&format!("{{%- set {BRACE} = \"{{\" %}}\n"));
    } else {
        out.push_str("#!yaml\n");
        out.push_str(BANNER);
    }
    for state in sls.all() {
        out.push('\n');
        out.push_str(&text.state(state));
    }
    out
}

/// The top file: the one host, matched as an exact minion ID and not as the
/// glob a bare key would be.
fn top_file(sls: &Sls) -> String {
    let document = Yaml::Map(vec![(
        "base".to_owned(),
        Yaml::Map(vec![(
            sls.host.clone(),
            Yaml::Seq(vec![
                Yaml::Map(vec![("match".to_owned(), Yaml::str("list"))]),
                Yaml::str(&sls.name),
            ]),
        )]),
    )]);
    format!("#!yaml\n{BANNER}\n{}", meridian_yaml::write(&document))
}

/// How strings are written into one file.
struct Text<'a> {
    /// Whether the file is rendered through Jinja before it is read as YAML.
    jinja: bool,
    /// The names of the secrets the states refer to.
    secrets: &'a [meridian_sdk::SecretName],
}

impl Text<'_> {
    /// One state: its ID, its function, then the arguments and requisites as
    /// Salt's list of single-key mappings. Key order is part of the output's
    /// identity, so it is decided here once.
    fn state(&self, state: &State) -> String {
        let mut items: Vec<Yaml> = state
            .args
            .iter()
            .map(|(key, value)| Yaml::Map(vec![(self.escape(key), self.value(value))]))
            .collect();
        for (kind, references) in [
            ("require", &state.require),
            ("watch", &state.watch),
            ("onchanges", &state.onchanges),
        ] {
            if !references.is_empty() {
                items.push(Yaml::Map(vec![(
                    kind.to_owned(),
                    Yaml::Seq(references.iter().map(|r| self.reference(r)).collect()),
                )]));
            }
        }
        let document = Yaml::Map(vec![(
            self.escape(&state.id),
            Yaml::Map(vec![(
                format!("{}.{}", state.module, state.function),
                Yaml::Seq(items),
            )]),
        )]);
        let mut out = meridian_yaml::write(&document);
        if !state.when.is_empty() {
            // The state stays in the file whatever the condition says, so a
            // requisite that names it still resolves. When the condition is
            // false the state is given an `unless` that always holds: Salt
            // skips it and counts it as succeeded. `exit 0` is the one
            // command every shell a minion may use agrees on.
            out.push_str(&format!(
                "{{%- if not ({}) %}}\n{ARGUMENT_INDENT}- unless: exit 0\n{{%- endif %}}\n",
                state.when
            ));
        }
        out
    }

    fn reference(&self, reference: &Reference) -> Yaml {
        Yaml::Map(vec![(
            reference.module.to_owned(),
            Yaml::Str(self.escape(&reference.id)),
        )])
    }

    /// Renders a param value. Map keys arrive sorted, so a value serialises
    /// identically every time.
    fn value(&self, value: &Value) -> Yaml {
        match value {
            Value::Null => Yaml::Null,
            Value::Bool(b) => Yaml::Bool(*b),
            Value::Int(i) => Yaml::Int(*i),
            Value::Uint(u) => Yaml::Uint(*u),
            Value::Float(f) => Yaml::Float(*f),
            Value::String(s) => Yaml::Str(self.escape(s)),
            // A secret is read from the pillar when the file is rendered: the
            // reference is Jinja, written as it is, and what it renders to is
            // the scalar YAML reads. One the graph does not name is written
            // as its mask.
            Value::Secret(at) => self
                .secrets
                .iter()
                .find(|s| s.secret == *at)
                .map(|s| Yaml::Raw(crate::secret_reference(&s.name)))
                .unwrap_or_else(|| Yaml::str(meridian_sdk::SENSITIVE)),
            Value::List(items) => Yaml::Seq(items.iter().map(|v| self.value(v)).collect()),
            Value::Map(map) => Yaml::Map(
                map.iter()
                    .map(|(key, value)| (self.escape(key), self.value(value)))
                    .collect(),
            ),
        }
    }

    /// A string as it must be written for the file to mean it literally.
    ///
    /// In a file rendered through Jinja, `{{`, `{%` and `{#` open a tag. The
    /// brace of each is replaced with an expression that renders a brace, so
    /// the text Jinja hands to YAML is the text the author wrote. The
    /// expression holds no quote and no backslash, which is what lets it sit
    /// inside any style of YAML scalar without being altered by it.
    fn escape(&self, s: &str) -> String {
        if !self.jinja || !s.contains('{') {
            return s.to_owned();
        }
        let mut out = String::with_capacity(s.len());
        let mut chars = s.chars().peekable();
        while let Some(c) = chars.next() {
            if c == '{' && matches!(chars.peek(), Some('{' | '%' | '#')) {
                out.push_str(&format!("{{{{{BRACE}}}}}"));
            } else {
                out.push(c);
            }
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_plain_file_leaves_every_string_alone() {
        let text = Text {
            jinja: false,
            secrets: &[],
        };
        assert_eq!(
            text.escape("{{ a }} {% b %} {# c #}"),
            "{{ a }} {% b %} {# c #}"
        );
    }

    #[test]
    fn a_rendered_file_replaces_the_brace_that_opens_a_tag() {
        let text = Text {
            jinja: true,
            secrets: &[],
        };
        assert_eq!(text.escape("server {}"), "server {}");
        assert_eq!(text.escape("{\"a\": 1}"), "{\"a\": 1}");
        // Only a brace that opens a tag is replaced: the second of a pair
        // opens nothing once the first is gone.
        assert_eq!(text.escape("{{ a }}"), "{{meridian_brace}}{ a }}");
        assert_eq!(text.escape("{% b %}"), "{{meridian_brace}}% b %}");
        assert_eq!(text.escape("{# c #}"), "{{meridian_brace}}# c #}");
        // Three braces: the first two are each followed by another.
        assert_eq!(
            text.escape("{{{x"),
            "{{meridian_brace}}{{meridian_brace}}{x"
        );
        assert_eq!(text.escape("ends with {"), "ends with {");
    }
}
